class AdminLogin extends StatefulWidget{const AdminLogin({super.key});@override State<AdminLogin> createState()=>_AdminLoginState();}
class _AdminLoginState extends State<AdminLogin>{final email=TextEditingController(),password=TextEditingController();bool busy=false,hide=true;@override void dispose(){email.dispose();password.dispose();super.dispose();}
Future<void> signIn({bool google=false})async{setState(()=>busy=true);try{final c=google?await FirebaseAuth.instance.signInWithPopup(GoogleAuthProvider()):await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text);final u=c.user;if(u==null)throw Exception('Sign in failed');final d=await FirebaseFirestore.instance.collection('users').doc(u.uid).get();if(!d.exists||d.data()?['role']!='admin'){await FirebaseAuth.instance.signOut();throw Exception('This account is not an administrator');}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>busy=false);}}
